type Row = Record<string, unknown>

/** What a widget is: a number, a chart, a ranking, a table. */
export type WidgetKind = "stat" | "area" | "line" | "bar" | "combo" | "donut" | "progress" | "goal" | "top" | "table" | "radar" | "timeline"

/** How wide a widget's card is, of the grid's width. */
export type WidgetWidth = "third" | "half" | "two_thirds" | "full"

/** A report on a dashboard, as the model marks it. */
export interface Widget {
  name: string
  label: string
  kind: WidgetKind
  x?: string
  /** The columns of the numbers: a series each. */
  y: string[]
  /** A column whose values split the rows into series. */
  series?: string
  since?: string
  until?: string
  /** How a number is reckoned from its rows: summed, the last, their average, the greatest. */
  total?: "sum" | "last" | "average" | "max"
  target?: string
  image?: string
  subtitle?: string
  delta?: string
  width?: WidgetWidth
  /** A Lucide icon for a number: shopping_cart. */
  icon?: string
  /** The dashboard it is on (its address); none, the first page's. */
  dashboard?: string
  /** How many rows a ranking, a list, a timeline or a table shows. */
  rows?: number
  columns: FieldMeta[]
  fetch: (api: never, params: Record<string, unknown>, signal?: AbortSignal) => Promise<Row[]>
}

const DAY = 86_400_000

/** The period a dashboard opens with. */
const DEFAULT_PERIOD = "30d"

/** A period: its start (none: all time). */
interface Period {
  key: string
  label: string
  since?: Date
}

function periods(): Period[] {
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  return [
    { key: "today", label: t("today"), since: today },
    { key: "7d", label: t("last7days"), since: new Date(today.getTime() - 6 * DAY) },
    { key: "30d", label: t("last30days"), since: new Date(today.getTime() - 29 * DAY) },
    { key: "month", label: t("thisMonth"), since: new Date(today.getFullYear(), today.getMonth(), 1) },
    { key: "90d", label: t("last90days"), since: new Date(today.getTime() - 89 * DAY) },
    { key: "all", label: t("allTime") },
  ]
}

/**
 * The period before a period, as long: what a number is compared with. Its
 * bounds are whole days (up to the end of today), so they stay the same
 * between renders: a query's key must not change by the millisecond.
 */
export function previous(since?: Date): { since: Date; until: Date } | undefined {
  if (!since) return undefined
  const now = new Date()
  const end = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1).getTime()
  return { since: new Date(since.getTime() - (end - since.getTime())), until: since }
}

const WIDTHS: Record<WidgetWidth, string> = {
  third: "md:col-span-6 lg:col-span-4",
  half: "md:col-span-6",
  two_thirds: "lg:col-span-8",
  full: "",
}

/** How wide a widget is: its own width, or its kind's. */
export function widthOf(w: Widget): WidgetWidth {
  if (w.width) return w.width
  if (w.kind === "table" || w.kind === "stat") return "full"
  if (w.kind === "area" || w.kind === "line" || w.kind === "bar" || w.kind === "combo") return "two_thirds"
  return "third"
}

/**
 * A dashboard: its widgets (the first page's, or a dashboard's by its
 * address), the period at the right of its title, the numbers together in
 * an overview, the rest in a grid by their widths.
 */
export function Dashboard({
  widgets = declared,
  dashboard,
  title,
  description,
}: {
  widgets?: Widget[]
  /** A dashboard's address; none, the first page's. */
  dashboard?: string
  title?: string
  description?: string
}) {
  // The period and the number drawn are in the URL (?period=7d&kpi=orders):
  // a dashboard's link opens it as it was; the defaults stay out of it.
  const search = useSearch({ strict: false }) as { period?: string; kpi?: string }
  const navigate = useNavigate()
  const period = periods().some((p) => p.key === search.period) ? (search.period as string) : DEFAULT_PERIOD
  const picked = search.kpi
  const setSearch = (changes: { period?: string; kpi?: string }) =>
    navigate({ to: ".", search: (prev: Record<string, unknown>) => ({ ...prev, ...changes }) as never, replace: true })
  const setPeriod = (p: string) => setSearch({ period: p === DEFAULT_PERIOD ? undefined : p })
  const setPicked = (name: string) => setSearch({ kpi: name })
  const mine = widgets.filter((w) => w.dashboard === dashboard)
  const since = periods().find((p) => p.key === period)?.since
  const timed = mine.some((w) => w.since)
  const stats = mine.filter((w) => w.kind === "stat")
  const others = mine.filter((w) => w.kind !== "stat")
  // A number over a column (its x: a day) is drawn under the numbers, the
  // one picked; a number without one is only its total, and no button.
  const drawn = stats.filter((w) => w.x)
  const shown = drawn.find((w) => w.name === picked) ?? drawn[0]
  const trayWidth = stats[0] ? widthOf(stats[0]) : "full"
  const picker = timed && (
    <div className="flex items-center gap-2">
      <span className="hidden text-sm font-semibold text-muted-foreground sm:inline">{t("period")}:</span>
      <Select value={period} onValueChange={setPeriod}>
        <SelectTrigger className="h-10 w-44 bg-card shadow-xs" aria-label={t("period")}>
          <SelectValue />
        </SelectTrigger>
        <SelectContent align="end">
          {periods().map((p) => (
            <SelectItem key={p.key} value={p.key}>
              {p.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  )
  return (
    <div className="flex flex-col gap-4">
      {(title || picker) && <PageHeader title={title ?? ""} description={description} actions={picker || undefined} />}
      {mine.length === 0 && <p className="py-16 text-center text-sm text-muted-foreground">{t("noWidgets")}</p>}
      <div className="grid grid-flow-row-dense grid-cols-1 gap-4 md:grid-cols-12">
        {stats.length > 0 && (
          <Card className={cn("col-span-1 md:col-span-12", WIDTHS[trayWidth], trayWidth === "two_thirds" && "lg:row-span-2")}>
            <CardHeader>
              <CardTitle>{t("overview")}</CardTitle>
            </CardHeader>
            <CardContent>
              {/* The numbers, side by side in a tray, as many as fit. */}
              <div className="grid grid-cols-2 gap-2 rounded-2xl bg-muted p-2 *:last:odd:col-span-2 sm:grid-cols-[repeat(auto-fit,minmax(200px,1fr))] sm:gap-3 sm:p-3 sm:*:last:odd:col-span-1">
                {stats.map((w, i) => (
                  <StatTile
                    key={w.name}
                    widget={w}
                    since={since}
                    tone={i}
                    active={drawn.length > 1 && w.x ? w === shown : undefined}
                    onPick={drawn.length > 1 && w.x ? () => setPicked(w.name) : undefined}
                  />
                ))}
              </div>
              {shown && <TrendChart widget={shown} since={since} />}
            </CardContent>
          </Card>
        )}
        {others.map((w) => (
          <WidgetCard key={w.name} widget={w} since={since} className={cn("col-span-1 md:col-span-12", WIDTHS[widthOf(w)])} />
        ))}
      </div>
    </div>
  )
}

/** The colors of the numbers' icons, in turn. */
const TONES = [
  "bg-sky-200 text-neutral-900 dark:bg-sky-500/25 dark:text-sky-200",
  "bg-emerald-200 text-neutral-900 dark:bg-emerald-500/25 dark:text-emerald-200",
  "bg-violet-200 text-neutral-900 dark:bg-violet-500/25 dark:text-violet-200",
  "bg-orange-200 text-neutral-900 dark:bg-orange-500/25 dark:text-orange-200",
]

/** The colors of an enum's values, as a chart draws them. */
const ENUM_COLORS: Record<string, string> = {
  green: "#10b981",
  amber: "#f59e0b",
  red: "#ef4444",
  blue: "#3b82f6",
  violet: "#8b5cf6",
  sky: "#0ea5e9",
  orange: "#f97316",
  gray: "#a3a3a3",
}

/** The colors of series, in turn: the theme's chart colors. */
const PALETTE = ["var(--chart-1)", "var(--chart-2)", "var(--chart-3)", "var(--chart-4)", "var(--chart-5)"]

function paramsOf(w: Widget, since?: Date, until?: Date): Record<string, unknown> {
  const params: Record<string, unknown> = {}
  if (w.since && since) params[w.since] = since.toISOString()
  if (w.until && until) params[w.until] = until.toISOString()
  return params
}

function useRows(w: Widget, since?: Date, until?: Date, enabled = true) {
  const params = paramsOf(w, since, until)
  return useQuery({
    queryKey: ["reports", w.name, params],
    queryFn: ({ signal }) => w.fetch(api as never, params, signal),
    enabled,
    // Numbers of a period change slowly: going back to a dashboard within a
    // minute shows them again without asking.
    staleTime: 60_000,
  })
}

function columnOf(w: Widget, name?: string): FieldMeta | undefined {
  return w.columns.find((c) => c.name === name)
}

/** A value as people read it: money exact, a share as a percentage, seconds as a duration. */
export function display(c: FieldMeta | undefined, v: unknown): string {
  if (v === null || v === undefined || v === "") return "—"
  if (c?.format === "percent") return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(Number(v))
  if (c?.format === "duration") {
    const s = Math.round(Number(v))
    const p = (n: number) => String(n).padStart(2, "0")
    return s >= 3600 ? `${Math.floor(s / 3600)}:${p(Math.floor(s / 60) % 60)}:${p(s % 60)}` : `${p(Math.floor(s / 60))}:${p(s % 60)}`
  }
  if (c?.kind === "money" || isMoney(v)) return formatMoney(v)
  return format(c ?? ({ kind: "decimal" } as FieldMeta), v)
}

/** A number of the rows: y summed (money by currency), or their last, average or greatest. */
function totalOf(c: FieldMeta | undefined, rows: Row[], y: string, how: Widget["total"] = "sum"): string {
  if (how === "sum" && c?.kind === "money") return formatTotals(sumMoney(rows.map((r) => r[y])))
  const v = reckon(rows, y, how)
  if (c?.kind === "money") {
    const money = moneyOf(rows, c)
    return money ? formatMoney({ amount: String(v), currency: money }) : display(c, v)
  }
  return display(c ?? ({ kind: "decimal" } as FieldMeta), v)
}

/** The number of a column of the rows, by how it is reckoned. */
export function reckon(rows: Row[] | undefined, y: string, how: Widget["total"] = "sum"): number {
  const values = (rows ?? []).map((r) => Number(isMoney(r[y]) ? (r[y] as Money).amount : r[y]) || 0)
  if (values.length === 0) return 0
  if (how === "last") return values[values.length - 1]
  if (how === "max") return Math.max(...values)
  if (how === "average") return values.reduce((a, b) => a + b, 0) / values.length
  return values.reduce((a, b) => a + b, 0)
}

/** How a number changed from the period before: +3.4%, or nothing to compare. */
export function change(now: number, before: number): number | undefined {
  if (!Number.isFinite(now) || !Number.isFinite(before) || before === 0) return undefined
  return (now - before) / Math.abs(before)
}

/** A change, colored: green up, red down. */
function Delta({ value, suffix }: { value?: number; suffix?: string }) {
  if (value === undefined) return null
  const up = value >= 0
  const Icon = up ? TrendingUp : TrendingDown
  return (
    <span className="inline-flex items-center gap-1 text-xs font-semibold">
      <span className={cn("inline-flex items-center gap-0.5", up ? "text-success" : "text-destructive")}>
        <Icon className="size-3.5" />
        {up ? "+" : ""}
        {new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(value)}
      </span>
      {suffix && <span className="font-medium text-muted-foreground">{suffix}</span>}
    </span>
  )
}

/**
 * A number: its name, its icon in a colored circle, the number and, with
 * the period's end (until), how it changed from the period before. Among
 * numbers drawn over time, the one drawn is raised, and a click draws
 * another.
 */
function StatTile({
  widget: w,
  since,
  tone,
  active,
  onPick,
}: {
  widget: Widget
  since?: Date
  tone: number
  active?: boolean
  onPick?: () => void
}) {
  const y = w.y[0] ?? ""
  const rows = useRows(w, since)
  const before = previous(since)
  const prior = useRows(w, before?.since, before?.until, Boolean(w.until && before))
  const yCol = columnOf(w, y)
  const Icon = iconOf(w.icon, "ChartColumn")
  const Tile = onPick ? "button" : "div"
  const delta = rows.data && prior.data ? change(reckon(rows.data, y, w.total), reckon(prior.data, y, w.total)) : undefined
  return (
    <Tile
      {...(onPick && { type: "button" as const, onClick: onPick, "aria-pressed": active })}
      className={cn(
        "flex min-w-0 flex-col gap-2 rounded-xl p-3 text-left transition-[background-color,box-shadow] duration-150 sm:gap-3 sm:rounded-2xl sm:p-4",
        active === false ? "hover:bg-card/60" : "bg-card shadow-xs",
        active && "shadow-md",
        onPick && "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring",
      )}
    >
      {/* Its name and icon on a line, the number under them, its change last. */}
      <div className="flex items-start justify-between gap-3">
        <p className="line-clamp-2 min-w-0 pt-1 text-xs font-semibold text-muted-foreground sm:truncate sm:text-sm">{w.label}</p>
        <div className={cn("flex size-9 shrink-0 items-center justify-center rounded-full sm:size-12", TONES[tone % TONES.length])}>
          <Icon className="size-4 sm:size-5" />
        </div>
      </div>
      <div className="text-xl font-bold tracking-tight break-words text-foreground tabular-nums sm:text-2xl xl:text-3xl">
        {rows.isPending ? (
          <Skeleton className="h-9 w-24" />
        ) : rows.isError ? (
          <span
            role="button"
            tabIndex={0}
            className="text-base text-destructive underline-offset-4 hover:underline"
            title={describe(rows.error)}
            onClick={(e) => {
              e.stopPropagation()
              rows.refetch()
            }}
          >
            {t("retry")}
          </span>
        ) : (
          totalOf(yCol, rows.data, y, w.total)
        )}
      </div>
      {w.until && before && <Delta value={delta} suffix={t("vsPrevious")} />}
    </Tile>
  )
}

/** The number picked, drawn over its x: the same rows as its total. */
function TrendChart({ widget: w, since }: { widget: Widget; since?: Date }) {
  const rows = useRows(w, since)
  if (rows.isPending) return <Skeleton className="mt-6 h-64 w-full" />
  if (!rows.data || rows.data.length === 0) return <p className="py-10 text-center text-sm text-muted-foreground">{rows.isError ? describe(rows.error) : t("noData")}</p>
  return (
    <div className="mt-6">
      <SeriesChart widget={{ ...w, kind: "area" }} rows={rows.data} />
    </div>
  )
}

/** A widget in a card of its own: its title, and what it shows in its states. */
function WidgetCard({ widget: w, since, className }: { widget: Widget; since?: Date; className?: string }) {
  const rows = useRows(w, since)
  return (
    <Card className={cn("min-w-0", className)}>
      <CardHeader>
        <CardTitle>{w.label}</CardTitle>
      </CardHeader>
      <CardContent className="flex-1">
        {rows.isPending && <Skeleton className={w.kind === "table" || w.kind === "top" || w.kind === "progress" ? "h-48 w-full" : "h-64 w-full"} />}
        {rows.isError && (
          <div className="flex flex-col items-center gap-2 py-6 text-center text-sm text-destructive" role="alert">
            <TriangleAlert className="size-5" />
            <span>{describe(rows.error)}</span>
            <Button variant="outline" size="sm" onClick={() => rows.refetch()}>
              <RotateCw /> {t("retry")}
            </Button>
          </div>
        )}
        {rows.data && rows.data.length === 0 && <p className="py-10 text-center text-sm text-muted-foreground">{t("noData")}</p>}
        {rows.data && rows.data.length > 0 && <WidgetBody widget={w} rows={shownRows(w, rows.data)} />}
      </CardContent>
    </Card>
  )
}

/** The rows a widget shows: a ranking, a list or a table, its first ones; a chart, all. */
function shownRows(w: Widget, rows: Row[]): Row[] {
  // A list of shares cuts its rows itself, after reckoning them of the total.
  const listed = w.kind === "top" || w.kind === "timeline" || w.kind === "table"
  if (!listed) return rows
  return rows.slice(0, w.rows ?? (w.kind === "table" ? 8 : 6))
}

/** What a widget shows of its rows, by its kind. */
export function WidgetBody({ widget: w, rows }: { widget: Widget; rows: Row[] }): ReactNode {
  switch (w.kind) {
    case "area":
    case "line":
    case "bar":
    case "combo":
      return <SeriesChart widget={w} rows={rows} />
    case "donut":
      return <DonutChart widget={w} rows={rows} />
    case "progress":
      return <ProgressList widget={w} rows={rows} />
    case "goal":
      return <GoalRing widget={w} rows={rows} />
    case "top":
      return <TopList widget={w} rows={rows} />
    case "radar":
      return <RadarScores widget={w} rows={rows} />
    case "timeline":
      return <Timeline widget={w} rows={rows} />
    case "table":
      return <ReportTable rows={rows} columns={w.columns} />
    case "stat":
      return <p className="text-3xl font-bold tracking-tight tabular-nums">{totalOf(columnOf(w, w.y[0]), rows, w.y[0] ?? "", w.total)}</p>
  }
}

/** The rows with their names (x) as people read them: an enum's labels. */
function nameOf(c: FieldMeta | undefined, v: unknown): string {
  if (!c) return capitalize(String(v ?? "—"))
  if (c.kind === "date" || c.kind === "datetime") {
    const d = new Date(String(v).length === 10 ? `${v}T00:00:00` : String(v))
    if (!Number.isNaN(d.getTime())) return new Intl.DateTimeFormat(locale, { day: "2-digit", month: "short" }).format(d)
  }
  return capitalize(format(c, v))
}

/** The y column, summed over the rows. */
export function total(rows: Row[] | undefined, y?: string): number {
  return (rows ?? []).reduce((sum, r) => sum + (Number(isMoney(r[y ?? ""]) ? (r[y ?? ""] as Money).amount : r[y ?? ""]) || 0), 0)
}

/** The currency a money column's rows are in, for its chart. */
function moneyOf(rows: Row[], y?: FieldMeta): string | undefined {
  if (y?.kind !== "money") return undefined
  const first = rows.find((r) => isMoney(r[y.name]))
  return first ? currencyOf(first[y.name] as Money) : undefined
}

/** A chart's scale, short: 1,4 mil, or R$ 1,4 mil for money, 42% for a share. */
function tickOf(c?: FieldMeta, money?: string) {
  if (c?.format === "percent") return (v: number) => new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 }).format(v)
  const scale = new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1, ...(money && { style: "currency", currency: money }) })
  return (v: number) => scale.format(v)
}

/** The series of a chart: the y columns, or the values of the series column. */
interface Series {
  key: string
  label: string
  color: string
  column?: FieldMeta
}

/**
 * The rows as a chart draws them, one per x, and their series. The numbers
 * become numbers (an amount's text drawn as a number: the chart only places
 * it; what is read, the tooltip, is exact).
 */
export function chartData(w: Widget, rows: Row[]): { data: Row[]; series: Series[]; money?: string } {
  const x = w.x ?? ""
  const xCol = columnOf(w, x)
  const num = (v: unknown) => Number(isMoney(v) ? v.amount : v) || 0
  if (w.series) {
    const sCol = columnOf(w, w.series)
    const y = w.y[0] ?? ""
    const keys: string[] = []
    const byX = new Map<string, Row>()
    for (const r of rows) {
      const k = String(r[w.series] ?? "—")
      if (!keys.includes(k)) keys.push(k)
      const name = nameOf(xCol, r[x])
      const row = byX.get(name) ?? { __x: name }
      row[`s${keys.indexOf(k)}`] = num(r[y])
      byX.set(name, row)
    }
    return {
      data: [...byX.values()],
      series: keys.map((k, i) => ({
        key: `s${i}`,
        label: nameOf(sCol, k),
        color: (sCol?.colors && ENUM_COLORS[sCol.colors[k] ?? ""]) || PALETTE[i % PALETTE.length],
        column: columnOf(w, y),
      })),
      money: moneyOf(rows, columnOf(w, y)),
    }
  }
  return {
    data: rows.map((r) => {
      const row: Row = { __x: nameOf(xCol, r[x]) }
      w.y.forEach((y, i) => (row[`s${i}`] = num(r[y])))
      return row
    }),
    series: w.y.map((y, i) => ({ key: `s${i}`, label: columnOf(w, y)?.label ?? y, color: PALETTE[i % PALETTE.length], column: columnOf(w, y) })),
    money: moneyOf(rows, columnOf(w, w.y[0])),
  }
}

/** A tooltip of the chart's own values, each as people read it (money exact, a share as %). */
function tooltipOf(series: Series[], money?: string) {
  return (
    <ChartTooltipContent
      formatter={(value, name, item) => {
        const s = series.find((x) => x.key === name)
        const text =
          s?.column?.kind === "money" && money ? formatMoney({ amount: String(value), currency: money }) : display(s?.column, value)
        return (
          <div className="flex w-full items-center justify-between gap-4">
            <span className="flex items-center gap-2 text-muted-foreground">
              <span className="size-2.5 shrink-0 rounded-[3px]" style={ { background: item.color ?? s?.color } } />
              {s?.label ?? name}
            </span>
            <span className="font-semibold text-foreground tabular-nums">{text}</span>
          </div>
        )
      }}
    />
  )
}

/**
 * Areas, lines, bars, or bars and a line (combo), over the rows in their
 * order: days, months, names. Several series have a legend.
 */
export function SeriesChart({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const { data, series, money } = chartData(w, rows)
  const config = Object.fromEntries(series.map((s) => [s.key, { label: s.label, color: s.color }])) satisfies ChartConfig
  const tick = tickOf(series[0]?.column, money)
  const legend = series.length > 1 && <ChartLegend content={<ChartLegendContent />} />
  const axes = (
    <>
      <CartesianGrid vertical={false} strokeDasharray="4 4" />
      <XAxis dataKey="__x" tickLine={false} axisLine={false} tickMargin={10} minTickGap={24} />
      <YAxis tickLine={false} axisLine={false} tickMargin={8} width={money ? 76 : 48} tickFormatter={tick} />
      <ChartTooltip cursor={w.kind === "bar" || w.kind === "combo" ? { fill: "var(--muted)", radius: 8 } : true} content={tooltipOf(series, money)} />
      {legend}
    </>
  )
  if (w.kind === "bar") {
    // Long names lie down: the bars across.
    const across = data.length > 0 && data.some((d) => String(d.__x).length > 14)
    return (
      <ChartContainer config={config} className={cn("aspect-auto w-full", across ? "h-[max(16rem,calc(var(--rows)*2.75rem))]" : "h-72")} style={ { "--rows": data.length } as CSSProperties }>
        <BarChart data={data} layout={across ? "vertical" : "horizontal"} accessibilityLayer margin={ { left: 0, right: 8 } }>
          {across ? (
            <>
              <CartesianGrid horizontal={false} strokeDasharray="4 4" />
              <YAxis type="category" dataKey="__x" tickLine={false} axisLine={false} width={120} />
              <XAxis type="number" tickLine={false} axisLine={false} tickFormatter={tick} />
              <ChartTooltip cursor={ { fill: "var(--muted)", radius: 8 } } content={tooltipOf(series, money)} />
              {legend}
            </>
          ) : (
            axes
          )}
          {series.map((s) => (
            <Bar key={s.key} dataKey={s.key} fill={`var(--color-${s.key})`} radius={across ? [0, 6, 6, 0] : [6, 6, 0, 0]} maxBarSize={across ? 24 : 40} />
          ))}
        </BarChart>
      </ChartContainer>
    )
  }
  if (w.kind === "combo") {
    const [bars, line] = series
    return (
      <ChartContainer config={config} className="aspect-auto h-72 w-full">
        <ComposedChart data={data} accessibilityLayer margin={ { left: 0, right: 0 } }>
          <CartesianGrid vertical={false} strokeDasharray="4 4" />
          <XAxis dataKey="__x" tickLine={false} axisLine={false} tickMargin={10} minTickGap={24} />
          <YAxis yAxisId="bars" tickLine={false} axisLine={false} tickMargin={8} width={money ? 76 : 48} tickFormatter={tick} />
          <YAxis yAxisId="line" orientation="right" tickLine={false} axisLine={false} tickMargin={8} width={44} tickFormatter={tickOf(line?.column)} />
          <ChartTooltip cursor={ { fill: "var(--muted)", radius: 8 } } content={tooltipOf(series, money)} />
          <ChartLegend content={<ChartLegendContent />} />
          {bars && <Bar yAxisId="bars" dataKey={bars.key} fill={`var(--color-${bars.key})`} radius={[6, 6, 0, 0]} maxBarSize={36} />}
          {line && <Line yAxisId="line" dataKey={line.key} type="monotone" stroke={`var(--color-${line.key})`} strokeWidth={3} dot={false} activeDot={ { r: 5 } } />}
        </ComposedChart>
      </ChartContainer>
    )
  }
  if (w.kind === "line") {
    return (
      <ChartContainer config={config} className="aspect-auto h-72 w-full">
        <Lines data={data} accessibilityLayer margin={ { left: 0, right: 8 } }>
          {axes}
          {series.map((s) => (
            <Line key={s.key} dataKey={s.key} type="monotone" stroke={`var(--color-${s.key})`} strokeWidth={3} dot={false} activeDot={ { r: 5 } } />
          ))}
        </Lines>
      </ChartContainer>
    )
  }
  return (
    <ChartContainer config={config} className="aspect-auto h-72 w-full">
      <AreaChart data={data} accessibilityLayer margin={ { left: 0, right: 8 } }>
        <defs>
          {series.map((s) => (
            <linearGradient key={s.key} id={`fill-${w.name}-${s.key}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={`var(--color-${s.key})`} stopOpacity={0.3} />
              <stop offset="95%" stopColor={`var(--color-${s.key})`} stopOpacity={0.02} />
            </linearGradient>
          ))}
        </defs>
        {axes}
        {series.map((s) => (
          <Area
            key={s.key}
            dataKey={s.key}
            type="monotone"
            stroke={`var(--color-${s.key})`}
            strokeWidth={2.5}
            fill={`url(#fill-${w.name}-${s.key})`}
            dot={false}
            activeDot={ { r: 5 } }
          />
        ))}
      </AreaChart>
    </ChartContainer>
  )
}

/** Each name's share of the rows (x and y): its color, and its percentage. */
function shares(w: Widget, rows: Row[]) {
  const xCol = columnOf(w, w.x)
  const y = w.y[0] ?? ""
  const sum = total(rows, y)
  return rows.map((r, i) => {
    const value = Number(isMoney(r[y]) ? (r[y] as Money).amount : r[y]) || 0
    const raw = String(r[w.x ?? ""] ?? "")
    return {
      key: `k${i}`,
      name: nameOf(xCol, r[w.x ?? ""]),
      value,
      text: display(columnOf(w, y), r[y]),
      share: sum ? value / sum : 0,
      color: (xCol?.colors && ENUM_COLORS[xCol.colors[raw] ?? ""]) || PALETTE[i % PALETTE.length],
    }
  })
}

const percent = (v: number) => new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }).format(v)

/** A total, short, for a small place: R$ 56 mil, 1,2 mi. */
function compact(c: FieldMeta | undefined, rows: Row[], y: string): string {
  const money = moneyOf(rows, c)
  return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1, ...(money && { style: "currency", currency: money }) }).format(total(rows, y))
}

/** A donut of each name's share, the total in its middle, the shares under it. */
export function DonutChart({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const parts = shares(w, rows)
  const y = w.y[0] ?? ""
  const config = Object.fromEntries(parts.map((p) => [p.key, { label: p.name, color: p.color }])) satisfies ChartConfig
  return (
    <div className="flex flex-col gap-4">
      <ChartContainer config={config} className="mx-auto aspect-square h-56">
        <PieChart>
          <ChartTooltip content={<ChartTooltipContent nameKey="key" hideLabel formatter={(_, __, item) => <span className="font-semibold">{(item.payload as { name: string; text: string }).name}: {(item.payload as { text: string }).text}</span>} />} />
          <Pie data={parts.map((p) => ({ ...p, fill: `var(--color-${p.key})` }))} dataKey="value" nameKey="key" innerRadius={62} outerRadius={92} paddingAngle={2} cornerRadius={6} strokeWidth={0}>
            <Label
              content={({ viewBox }) =>
                viewBox && "cx" in viewBox ? (
                  <text x={viewBox.cx} y={viewBox.cy} textAnchor="middle" dominantBaseline="middle">
                    <tspan x={viewBox.cx} y={(viewBox.cy ?? 0) - 6} className="fill-foreground text-xl font-bold">
                      {compact(columnOf(w, y), rows, y)}
                    </tspan>
                    <tspan x={viewBox.cx} y={(viewBox.cy ?? 0) + 16} className="fill-muted-foreground text-xs">
                      {t("total")}
                    </tspan>
                  </text>
                ) : null
              }
            />
          </Pie>
        </PieChart>
      </ChartContainer>
      <ul className="grid grid-cols-2 gap-x-4 gap-y-2.5">
        {parts.map((p) => (
          <li key={p.key} className="flex min-w-0 items-center gap-2 text-sm">
            <span className="size-2.5 shrink-0 rounded-full" style={ { background: p.color } } />
            <span className="min-w-0 flex-1 truncate text-muted-foreground">{p.name}</span>
            <span className="font-semibold tabular-nums">{percent(p.share)}</span>
          </li>
        ))}
      </ul>
    </div>
  )
}

/** Each name with its value and a bar of its share (of the total, or of its target). */
export function ProgressList({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const parts = shares(w, rows).slice(0, w.rows ?? 6)
  return (
    <ul className="flex flex-col gap-4">
      {parts.map((p, i) => {
        const target = w.target ? Number(rows[i]?.[w.target]) || 0 : 0
        const share = w.target ? (target ? p.value / target : 0) : p.share
        return (
          <li key={p.key} className="flex flex-col gap-1.5">
            <div className="flex items-baseline justify-between gap-3 text-sm">
              <span className="truncate font-semibold text-foreground">{p.name}</span>
              <span className="shrink-0 text-muted-foreground tabular-nums">
                {p.text} · <span className="font-semibold text-foreground">{percent(share)}</span>
              </span>
            </div>
            <div className="h-2 overflow-hidden rounded-full bg-muted">
              <div className="h-full rounded-full transition-[width] duration-500" style={ { width: `${Math.min(100, Math.max(0, share * 100))}%`, background: p.color } } />
            </div>
          </li>
        )
      })}
    </ul>
  )
}

/** A ring of y over its target: how far along, the number, and the goal. */
export function GoalRing({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const y = w.y[0] ?? ""
  const reached = total(rows, y)
  const goal = total(rows, w.target)
  const share = goal ? reached / goal : 0
  const r = 52
  const length = 2 * Math.PI * r
  return (
    <div className="flex items-center justify-between gap-6">
      <div className="flex min-w-0 flex-col gap-1">
        <p className="text-3xl font-bold tracking-tight tabular-nums">{totalOf(columnOf(w, y), rows, y)}</p>
        <p className="text-sm text-muted-foreground">{t("goalOf", { goal: totalOf(columnOf(w, w.target), rows, w.target ?? "") })}</p>
      </div>
      <div className="relative size-32 shrink-0">
        <svg viewBox="0 0 120 120" className="size-full -rotate-90">
          <circle cx="60" cy="60" r={r} fill="none" stroke="var(--muted)" strokeWidth="12" />
          <circle
            cx="60"
            cy="60"
            r={r}
            fill="none"
            stroke="var(--chart-1)"
            strokeWidth="12"
            strokeLinecap="round"
            strokeDasharray={`${Math.min(1, share) * length} ${length}`}
            className="transition-[stroke-dasharray] duration-700"
          />
        </svg>
        <span className="absolute inset-0 flex items-center justify-center text-lg font-bold tabular-nums">{percent(share)}</span>
      </div>
    </div>
  )
}

/** A ranking: each one's picture (or initials), name, second line, value and change. */
export function TopList({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const xCol = columnOf(w, w.x)
  const subCol = columnOf(w, w.subtitle)
  const deltaCol = columnOf(w, w.delta)
  const y = w.y[0] ?? ""
  return (
    <ul className="flex flex-col divide-y divide-border">
      {rows.map((r, i) => {
        const name = nameOf(xCol, r[w.x ?? ""])
        const image = w.image ? String(r[w.image] ?? "") : ""
        const d = w.delta ? Number(r[w.delta]) : NaN
        return (
          <li key={i} className="flex items-center gap-3 py-3 first:pt-0 last:pb-0">
            {image ? (
              <img src={image} alt="" loading="lazy" className="size-11 shrink-0 rounded-xl border border-border object-cover" />
            ) : (
              <span className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-muted text-xs font-bold text-muted-foreground">{initials(name)}</span>
            )}
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-semibold text-foreground">{name}</p>
              {w.subtitle && <p className="truncate text-xs text-muted-foreground">{display(subCol, r[w.subtitle])}</p>}
            </div>
            <div className="flex shrink-0 flex-col items-end gap-1">
              <span className="text-sm font-semibold tabular-nums">{display(columnOf(w, y), r[y])}</span>
              {Number.isFinite(d) && (
                <span className={cn("rounded-md px-1.5 py-0.5 text-[11px] font-bold tabular-nums", d >= 0 ? "bg-success/10 text-success" : "bg-destructive/10 text-destructive")}>
                  {d >= 0 ? "+" : ""}
                  {deltaCol?.format === "percent" ? percent(d) : `${d}%`}
                </span>
              )}
            </div>
          </li>
        )
      })}
    </ul>
  )
}

/** Scores on a radar, and the same scores numbered under it, colored by how high. */
export function RadarScores({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const { data, series } = chartData(w, rows)
  const config = Object.fromEntries(series.map((s) => [s.key, { label: s.label, color: s.color }])) satisfies ChartConfig
  const yCol = columnOf(w, w.y[0])
  const max = Math.max(...data.map((d) => Number(d.s0) || 0))
  return (
    <div className="flex flex-col gap-4">
      <ChartContainer config={config} className="mx-auto aspect-square h-56">
        <RadarChart data={data}>
          <ChartTooltip cursor={false} content={tooltipOf(series)} />
          <PolarGrid />
          <PolarAngleAxis dataKey="__x" tick={false} />
          {/* Shares are of 100%; other scores of the greatest. */}
          <PolarRadiusAxis domain={[0, yCol?.format === "percent" ? 1 : "auto"]} tick={false} axisLine={false} />
          {series.map((s) => (
            <Radar key={s.key} dataKey={s.key} fill={`var(--color-${s.key})`} fillOpacity={0.25} stroke={`var(--color-${s.key})`} strokeWidth={2} dot={ { r: 3, fillOpacity: 1 } } />
          ))}
        </RadarChart>
      </ChartContainer>
      <ol className="flex flex-col gap-2.5">
        {data.map((d, i) => {
          const v = Number(d.s0) || 0
          const level = yCol?.format === "percent" ? v : max ? v / max : 0
          return (
            <li key={i} className="flex items-center gap-3 text-sm">
              <span className="flex size-6 shrink-0 items-center justify-center rounded-full border border-border text-xs font-semibold">{i + 1}</span>
              <span className="min-w-0 flex-1 truncate">{String(d.__x)}</span>
              <span
                className={cn(
                  "rounded-md px-1.5 py-0.5 text-xs font-bold tabular-nums text-white",
                  level >= 0.7 ? "bg-emerald-500" : level >= 0.4 ? "bg-amber-500" : "bg-red-500",
                )}
              >
                {display(yCol, v)}
              </span>
            </li>
          )
        })}
      </ol>
    </div>
  )
}

/** What happened, newest first, on a line: who, what, and when. */
export function Timeline({ widget: w, rows }: { widget: Widget; rows: Row[] }) {
  const when = columnOf(w, w.x)
  const what = columnOf(w, w.y[0])
  const who = columnOf(w, w.subtitle)
  const time = (v: unknown) => {
    const d = new Date(String(v))
    return Number.isNaN(d.getTime()) ? display(when, v) : new Intl.DateTimeFormat(locale, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(d)
  }
  return (
    <ol className="relative flex flex-col gap-5 before:absolute before:top-2 before:bottom-2 before:left-[17px] before:w-px before:bg-border">
      {rows.map((r, i) => {
        const person = w.subtitle ? display(who, r[w.subtitle]) : ""
        return (
          <li key={i} className="relative flex gap-3">
            <span className="z-10 flex size-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary ring-4 ring-card">
              {person ? initials(person) : <Activity className="size-4" />}
            </span>
            <div className="min-w-0 flex-1 pt-0.5">
              {person && <p className="text-sm font-semibold text-foreground">{person}</p>}
              <p className="text-sm text-muted-foreground">{display(what, r[w.y[0] ?? ""])}</p>
              <p className="mt-0.5 text-xs text-muted-foreground/80">{time(r[w.x ?? ""])}</p>
            </div>
          </li>
        )
      })}
    </ol>
  )
}

/** The dot of an enum's value in a table, in its color. */
function Dot({ c, v }: { c: FieldMeta; v: unknown }) {
  const color = ENUM_COLORS[c.colors?.[String(v)] ?? "gray"] ?? ENUM_COLORS.gray
  return (
    <span className="inline-flex items-center gap-2 font-semibold" style={ { color } }>
      <span className="size-2 rounded-full" style={ { background: color } } />
      {format(c, v)}
    </span>
  )
}

/** A report's rows as a table: enums with their dots, money exact, shares with a bar. */
export function ReportTable({ rows, columns }: { rows: Row[]; columns: FieldMeta[] }) {
  return (
    <div className="max-h-96 overflow-auto">
      <Table>
        <TableHeader>
          <TableRow>
            {columns.map((c) => (
              <TableHead key={c.name} className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
                {c.label}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((r, i) => (
            <TableRow key={i}>
              {columns.map((c) => {
                const v = r[c.name]
                return (
                  <TableCell key={c.name} className={cn("py-3.5", (c.kind === "money" || c.kind === "int" || c.kind === "decimal") && "tabular-nums", c.kind === "money" && "font-semibold")}>
                    {v === null || v === undefined ? (
                      "—"
                    ) : c.kind === "enum" ? (
                      <Dot c={c} v={v} />
                    ) : c.format === "percent" ? (
                      <span className="flex items-center gap-3">
                        <span className="h-1.5 w-24 overflow-hidden rounded-full bg-muted">
                          <span
                            className={cn("block h-full rounded-full", Number(v) >= 0.7 ? "bg-emerald-500" : Number(v) >= 0.5 ? "bg-amber-500" : "bg-red-500")}
                            style={ { width: `${Math.min(100, Number(v) * 100)}%` } }
                          />
                        </span>
                        <span className="font-semibold tabular-nums">{display(c, v)}</span>
                      </span>
                    ) : (
                      display(c, v)
                    )}
                  </TableCell>
                )
              })}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

/** Bars of a report's rows (kept for pages of your own): x, the name of each; y, the number. */
export function BarsChart({ rows, x, y, label }: { rows: Row[]; x: string; y: string; label?: string; money?: string }) {
  return <SeriesChart widget={ { name: `bars-${y}`, label: label ?? y, kind: "bar", x, y: [y], columns: [], fetch: async () => rows } } rows={rows} />
}

/** A line over a report's rows (kept for pages of your own). */
export function LineChart({ rows, x, y, label }: { rows: Row[]; x: string; y: string; label?: string; money?: string }) {
  return <SeriesChart widget={ { name: `line-${y}`, label: label ?? y, kind: "line", x, y: [y], columns: [], fetch: async () => rows } } rows={rows} />
}
